#![forbid(unsafe_code)]
use serde_json::Value;use std::{fs,path::Path};
fn leer(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),7,"DATOS PAQUETE JUICIO ORIGINALES CAMPAÑA REPORTE");let bytes=fs::read(&a[1]).unwrap();let d:Value=serde_json::from_slice(&bytes).unwrap();sv_visor_pdf::validar(&d).unwrap();let p=leer(&a[2]);let j=leer(&a[3]);assert_eq!(j["autoridad"],"dictamen asistido exterior al candidato");assert_eq!(j["recepcion_independiente"],"pendiente");assert_eq!(d["juicio_sha256"],sv_visor_pdf::contrato::huella(&fs::read(&a[3]).unwrap()));for(case,row)in p["casos"].as_array().unwrap().iter().zip(d["casos"].as_array().unwrap()){assert_eq!(row["id"],case["id"]);let id=case["id"].as_str().unwrap();let q:Value=serde_json::from_str(case["base"]["input"][0]["content"].as_str().unwrap()).unwrap();assert_eq!(row["pregunta"],q["pregunta"]);for s in 0..3{let judgement:Vec<_>=j["adjudicaciones"].as_array().unwrap().iter().filter(|v|v["caso"]==id&&v["etapa"]==s).collect();assert_eq!(judgement.len(),1);let r=&row["etapas"][s];let old=id=="C01"||(id=="C02"&&s==0);let folder=if old{Path::new(&a[4]).join(format!("campana/cyb16/{id}-R{s}"))}else{Path::new(&a[5]).join(format!("cyb09/{id}-R{s}"))};let b=fs::read(folder.join("FINAL.txt")).unwrap();let f:Value=serde_json::from_slice(&b).unwrap();assert_eq!(r["valor"],judgement[0]["valor"]);assert_eq!(r["fundamento"],judgement[0]["motivo"]);assert_eq!(r["final_sha256"],sv_visor_pdf::contrato::huella(&b));assert_eq!(r["final_sha256"],judgement[0]["final_sha256"]);assert_eq!(r["respuesta"],f["respuesta"]);assert_eq!(r["informe_operativo"],f["informe_operativo"]);}}let report=serde_json::json!({"conforme":true,"posiciones":9,"entregas_cotejadas":27,"datos_sha256":sv_visor_pdf::contrato::huella(&bytes),"juicio_sha256":d["juicio_sha256"],"sin_inferencia":true,"recepcion_independiente":"pendiente","licencia":sv_visor_pdf::PIE});fs::write(&a[6],serde_json::to_vec_pretty(&report).unwrap()).unwrap();println!("Datos del visor: 27 correspondencias con los originales y el juicio exterior, sin inferencia");}
